### file: functions/_middleware.js
// Runs only on the paths listed in _routes.json; context.next() serves everything else from static assets.
const RETIRED = [/^\/old-product\/?$/, /^\/old-section\//];
export async function onRequest(context) {
  const url = new URL(context.request.url);
  if (!RETIRED.some((re) => re.test(url.pathname))) return context.next();
  const page = await context.env.ASSETS.fetch(new URL('/410', url)); // pretty path of 410.html
  const headers = new Headers(page.headers);
  headers.delete('content-encoding');
  headers.delete('content-length');
  headers.set('x-robots-tag', 'noindex');
  return new Response(page.body, { status: 410, headers });
}
