(function () {
  var form = document.getElementById('contact-form');
  if (!form) return;
  var status = document.getElementById('contact-status');
  var button = form.querySelector('button[type="submit"]');
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    button.disabled = true;
    status.textContent = 'Sending...';
    var ctl = new AbortController();
    var timer = setTimeout(function () { ctl.abort(); }, 10000);
    fetch(form.action, { method: 'POST', body: new FormData(form), headers: { Accept: 'application/json' }, credentials: 'omit', signal: ctl.signal })
      .then(function (res) {
        if (res.status === 429) throw new Error('rate');
        if (!res.ok) throw new Error('http ' + res.status); // success is shown ONLY for 2xx (RES-008)
        form.reset();
        status.textContent = 'Thank you, we will reply soon.';
      })
      .catch(function (err) {
        status.textContent = err.message === 'rate'
          ? 'Too many attempts. Please try again later.'
          : 'Sorry, your message was not sent. Please try again or email us.';
      })
      .finally(function () { clearTimeout(timer); button.disabled = false; });
  });
})();

Static hosts cannot make a per-request nonce, so a build step hashes every inline script, adds SRI `integrity` to same-origin scripts and writes `_headers` (Netlify and Cloudflare Pages read it from the publish dir; Vercel: set HOST=vercel and merge the written `vercel.headers.json` "headers" array into vercel.json). Run it last, after the generator. Do not hand-edit the built HTML afterwards and turn off host-side minify, bundling and snippet injection: any byte change breaks the hashes. Cloudflare Pages allows 100 rules and 2,000 characters per `_headers` line (the script refuses longer). HTML keeps the hosts' default `Cache-Control: public, max-age=0, must-revalidate`; only content-hashed asset names go in IMMUTABLE_DIRS (default `/assets`; set it empty if your file names carry no hash).
