// Post-build step: node scripts/csp-hashes.mjs dist   (Node 18+, no dependencies)
// Static HTML has no per-request nonce, so every inline script is allowed by its SHA-256 hash and every
// same-origin external script by its SRI integrity hash (CSP3 hash matching); 'strict-dynamic' then trusts
// scripts those create (the consent loader's Google tag) and makes host sources irrelevant (SEC-075).
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';

const OUT = resolve(process.argv[2] || 'dist');
const env = process.env;
const IMMUTABLE_DIRS = (env.IMMUTABLE_DIRS ?? '/assets').split(',').filter(Boolean); // content-hashed file names only (PRF-008)
const sha = (buf) => 'sha256-' + createHash('sha256').update(buf).digest('base64');
const inline = (text) => sha(text.replace(/\r\n?/g, '\n')); // the HTML parser turns CRLF into LF before the browser hashes
const attr = (a, n) => {
  const m = new RegExp(`(?:^|\\s)${n}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i').exec(a);
  return m ? (m[1] ?? m[2] ?? m[3]) : null;
};
const htmlFiles = (d) => readdirSync(d, { withFileTypes: true }).flatMap((e) =>
  e.isDirectory() ? htmlFiles(join(d, e.name)) : e.name.endsWith('.html') ? [join(d, e.name)] : []);

const scriptHashes = new Set(), styleHashes = new Set(), problems = [];
let styleAttr = false;
for (const file of htmlFiles(OUT)) {
  let html = readFileSync(file, 'utf8');
  html = html.replace(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi, (tag, a, body) => {
    const type = (attr(a, 'type') || '').trim().toLowerCase();
    if (!['', 'module', 'text/javascript', 'application/javascript', 'importmap'].includes(type)) return tag; // JSON-LD never executes
    const src = attr(a, 'src');
    if (src === null) { if (body.trim()) scriptHashes.add(inline(body)); return tag; }
    if (/^([a-z][a-z0-9+.-]*:)?\/\//i.test(src)) { problems.push(`${file}: cross-origin script ${src} - self-host it`); return tag; }
    const p = src.split(/[?#]/)[0];
    const h = sha(readFileSync(p.startsWith('/') ? join(OUT, p) : join(dirname(file), p)));
    scriptHashes.add(h);
    const rest = a.replace(/\sintegrity\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/i, '');
    return `<script${rest} integrity="${h}">${body}</script>`;
  });
  for (const m of html.matchAll(/<style\b[^>]*>([\s\S]*?)<\/style>/gi)) if (m[1].trim()) styleHashes.add(inline(m[1]));
  if (/<[a-z][^>]*\sstyle\s*=/i.test(html)) styleAttr = true;
  if (/<[a-z][^>]*\son[a-z]+\s*=\s*["']/i.test(html)) problems.push(`${file}: inline event-handler attribute (CSP blocks it) - use addEventListener`);
  writeFileSync(file, html);
}
if (problems.length) { console.error(problems.join('\n')); process.exit(1); }

const q = (s) => [...s].sort().map((h) => `'${h}'`).join(' ');
// style="" attributes cannot be hashed: only then relax the style directive (never the script one)
const styleSources = styleAttr ? "'unsafe-inline'" : q(styleHashes);
const csp = [
  "default-src 'self'",
  `script-src 'self' 'strict-dynamic' ${q(scriptHashes)}`.trim(),
  `style-src 'self' ${styleSources}`.trim(),
  `img-src 'self' data: ${env.CSP_IMG_EXTRA || ''}`.trim(),
  "font-src 'self'",
  `connect-src 'self' ${env.CSP_CONNECT_EXTRA || ''}`.trim(), // analytics beacons and your API origin go here
  "object-src 'none'",
  "base-uri 'self'",
  `form-action 'self' ${env.CSP_FORM_EXTRA || ''}`.trim(), // cross-origin <form action> endpoint, if any
  "frame-ancestors 'none'",
  'upgrade-insecure-requests',
].join('; ');
if (csp.length > 1900) { console.error(`CSP is ${csp.length} chars; Cloudflare Pages caps a _headers line at 2000`); process.exit(1); }

const all = [
  ['Content-Security-Policy', csp],
  ['X-Content-Type-Options', 'nosniff'],
  ['Referrer-Policy', 'strict-origin-when-cross-origin'],
  ['Permissions-Policy', 'camera=(), microphone=(), geolocation=()'],
  ['Strict-Transport-Security', 'max-age=63072000; includeSubDomains'],
];
if (env.DEPLOY_ENV !== 'production') all.push(['X-Robots-Tag', 'noindex, nofollow']); // IDX-005: never on production
// Cache-Control is NOT set on /*: both hosts already send "public, max-age=0, must-revalidate" for HTML, and two
// matching rules would be joined into one invalid value (Cloudflare joins same-name headers with a comma).
let out = '/*\n' + all.map(([k, v]) => `  ${k}: ${v}`).join('\n') + '\n';
for (const d of IMMUTABLE_DIRS) out += `${d}/*\n  Cache-Control: public, max-age=31536000, immutable\n`;
writeFileSync(join(OUT, '_headers'), out);
if (env.HOST === 'vercel') { // Vercel ignores _headers: merge this "headers" array into vercel.json
  const rule = (source, pairs) => ({ source, headers: pairs.map(([key, value]) => ({ key, value })) });
  writeFileSync('vercel.headers.json', JSON.stringify({ headers: [rule('/(.*)', all),
    ...IMMUTABLE_DIRS.map((d) => rule(`${d}/(.*)`, [['Cache-Control', 'public, max-age=31536000, immutable']]))] }, null, 2));
}
console.log(`csp-hashes: ${scriptHashes.size} script hash(es), ${styleHashes.size} style hash(es), _headers written`);
